use macshell_clock_core::audio::{ClockAudio,ClockPreview};
use serde_json::{json,Value};
use std::io::{self,BufRead,Write};
use std::path::PathBuf;
fn main(){let args:Vec<_>=std::env::args().skip(1).collect();let mut audio=ClockAudio::new(PathBuf::from(&args[0]),PathBuf::from(&args[1]),PathBuf::from(&args[2]));let mut preview=ClockPreview::new(PathBuf::from(&args[2]));for line in io::stdin().lock().lines().map_while(std::result::Result::ok){let r:Value=serde_json::from_str(&line).unwrap();let boot=r["boot"].as_u64().unwrap_or(0);let result=match r["op"].as_str().unwrap(){"start"=>audio.start(&r["event"],boot,r["path"].as_str().map(std::path::Path::new)),"tick"=>{audio.tick(r.get("event"),boot);Ok(())},"stop"=>{audio.stop();Ok(())},"preview"=>preview.start(r["id"].as_str().unwrap(),std::path::Path::new(r["path"].as_str().unwrap()),boot,r.get("options")),"preview-tick"=>{preview.tick(boot);Ok(())},_=>Err("unknown".into())};println!("{}",json!({"success":result.is_ok(),"error":result.err(),"pid":audio.child_id(),"failed":audio.failed,"fallback":audio.fallback_used,"finished":audio.finished,"previewPid":preview.child_id(),"previewId":preview.sound_id}));let _=io::stdout().flush();}}
